import sys

memo = {0: ['']}

def balanced(n):
    if n in memo:
        return memo[n]
    res = []
    for k in range(n):
        for a in balanced(k):
            for b in balanced(n - 1 - k):
                res.append('(' + a + ')' + b)
    memo[n] = res
    return res

data = sys.stdin.read().split()
t = int(data[0])
print('\n'.join(' '.join(sorted(balanced(int(data[1 + i])))) for i in range(t)))

